44: function init(){scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,230);camera.position.set(0,7,10);renderer=new THREE.WebGLRenderer({antialias:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;game.appendChild(renderer.domElement);clock3=new THREE.Clock();buildWorld();player=makeHero();spawnEnemies();player.position.set(0,terrainHeight(0,0)+.08,0);scene.add(new THREE.AmbientLight(0xffffff,.16));window.addEventListener('resize',resize);animate()}
